from pathlib import Path
import sys

path = Path(sys.argv[1])
s = path.read_text()

s = s.replace('–', '-').replace('—', '-')
s = s.replace('<option value="0.02">Outlined regions</option>', '<option value="0.01">Outlined regions</option>')
s = s.replace('nv.setAtlasOutline(.02)', 'nv.setAtlasOutline(.01)')

s = s.replace(
"function setTeachingOpacity(){if(!userOpacityTouched){op.value=45;opv.textContent='45%'}}\nfunction selectStructure(src,ids,label){ids=(Array.isArray(ids)?ids:[ids]).filter(i=>i>0);if(!ids.length)return;setSel(label);const key=src+ids.join(',');if(key===currentSource+currentIds.join(','))return;currentSource=src;currentIds=ids;setTeachingOpacity();",
"function setTeachingOpacity(force=false){if(force||!userOpacityTouched){op.value=45;opv.textContent='45%'}}\nfunction selectStructure(src,ids,label,forceVisible=false){ids=(Array.isArray(ids)?ids:[ids]).filter(i=>i>0);if(!ids.length)return;setSel(label);const key=src+ids.join(',');currentSource=src;currentIds=ids;setTeachingOpacity(forceVisible);"
)

s = s.replace(
"function nearestLabel(src,r=2){const i=vIdx(src),vol=nv.volumes?.[i];if(!vol||!vol.mm2vox||!vol.getValue)return 0;const mm=nv.frac2mm(nv.scene.crosshairPos),v=vol.mm2vox(mm);let best=0,bd=1e9;for(let dz=-r;dz<=r;dz++)for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++){const d=dx*dx+dy*dy+dz*dz;if(d>r*r||d>=bd)continue;const val=Math.round(vol.getValue(v[0]+dx,v[1]+dy,v[2]+dz));if(val>0){best=val;bd=d}}return best}",
"function nearestLabel(src,r=2){const i=vIdx(src),vol=nv.volumes?.[i];if(!vol||!vol.mm2vox||!vol.getValue)return null;const mm=nv.frac2mm(nv.scene.crosshairPos),v=vol.mm2vox(mm);let best=0,bd=1e9;for(let dz=-r;dz<=r;dz++)for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++){const d=dx*dx+dy*dy+dz*dz;if(d>r*r||d>=bd)continue;const val=Math.round(vol.getValue(v[0]+dx,v[1]+dy,v[2]+dz));if(val>0){best=val;bd=d}}return best?{id:best,d:Math.sqrt(bd)}:null}\nfunction midlineVentricleAtCursor(){const mm=nv.frac2mm(nv.scene.crosshairPos),x=Math.abs(mm[0]),y=mm[1],z=mm[2];if(x<=3.5&&y>=-27&&y<=1&&z>=-7&&z<=14)return'Third ventricle';if(x<=6&&y>=-47&&y<=-25&&z>=-42&&z<=-16)return'Fourth ventricle';return''}"
)

s = s.replace(
"function brainstemLevel(){const z=nv.frac2mm(nv.scene.crosshairPos)[2];if(z>-24)return'Midbrain level';if(z>-46)return'Pons level';return'Medulla level'}",
"function brainstemLevel(){const z=nv.frac2mm(nv.scene.crosshairPos)[2];if(z>-18)return'Rostral midbrain';if(z>-25)return'Caudal midbrain';if(z>-34)return'Rostral pons';if(z>-43)return'Caudal pons';if(z>-53)return'Rostral medulla';return'Caudal medulla'}"
)

s = s.replace(
"'midbrain':{mm:[0,-20,-12],title:'Midbrain level'},\n'pons':{mm:[0,-30,-32],title:'Pons level'},\n'medulla':{mm:[0,-34,-50],title:'Medulla level'},",
"'midbrain':{mm:[0,-20,-12],title:'Midbrain level'},\n'rostral midbrain':{mm:[0,-20,-8],title:'Rostral midbrain'},\n'caudal midbrain':{mm:[0,-24,-17],title:'Caudal midbrain'},\n'pons':{mm:[0,-30,-32],title:'Pons level'},\n'rostral pons':{mm:[0,-27,-28],title:'Rostral pons'},\n'caudal pons':{mm:[0,-34,-39],title:'Caudal pons'},\n'medulla':{mm:[0,-34,-50],title:'Medulla level'},\n'rostral medulla':{mm:[0,-36,-48],title:'Rostral medulla'},\n'caudal medulla':{mm:[0,-38,-58],title:'Caudal medulla'},"
)

old = "function brainstemDetail(level){if(level==='Midbrain level')return{s:'Brainstem · midbrain level',p:'Axial foremost',r:'The midbrain lies between the diencephalon and pons. On axial MRI, the cerebral peduncles are ventral, the tegmentum is central, the tectum is dorsal, and the cerebral aqueduct is a small midline CSF channel.',n:['Ventral: cerebral peduncles','Central: tegmentum with red nucleus and substantia nigra territory','Dorsal: superior/inferior collicular tectum depending on level','Midline: cerebral aqueduct'],f:'Carries ascending and descending long tracts and contains nuclei important for eye movements, arousal and motor control.',c:'Midbrain lesions can combine long-tract deficits with oculomotor or pupillary findings. The JHU overlay can identify cerebral peduncle, medial lemniscus and superior cerebellar peduncle territories.',t:'Scroll through consecutive axial levels from upper pons to diencephalon. Watch the peduncles, aqueduct and tectum change together.'};if(level==='Pons level')return{s:'Brainstem · pons level',p:'Axial foremost',r:'The pons has a ventral basis pontis containing corticospinal and transverse pontocerebellar fibers, and a dorsal tegmentum immediately anterior to the fourth ventricle.',n:['Ventral: basis pontis and descending corticospinal fibers','Lateral: middle cerebellar peduncles','Dorsal: pontine tegmentum','Posterior: fourth ventricle at upper and mid pontine levels'],f:'Relays corticocerebellar information and contains major ascending and descending tracts plus cranial nerve nuclei.',c:'Pontine lesions may produce combinations of long-tract, facial, gaze, vestibular and cerebellar findings depending on level.',t:'Follow the pons rostrocaudally. Compare the broad middle cerebellar peduncles laterally with the compact dorsal tegmentum and ventral basis.'};return{s:'Brainstem · medulla level',p:'Axial foremost',r:'The medulla is the caudal brainstem. On axial sections, the pyramids lie ventromedially, the inferior olives are anterolateral at rostral levels, and the dorsal medulla relates to the fourth ventricle rostrally and central canal caudally.',n:['Ventromedial: pyramidal corticospinal fibers','Anterolateral: inferior olivary region at rostral medulla','Posterolateral: inferior cerebellar peduncle territory','Dorsal: fourth ventricle rostrally, gracile/cuneate region caudally'],f:'Contains vital autonomic centers, lower cranial nerve nuclei and ascending/descending long tracts.',c:'Medullary lesions can combine corticospinal, dorsal-column/medial lemniscal, spinothalamic, cerebellar and lower cranial nerve findings.',t:'Scroll from the pontomedullary junction downward. Note the transition from an open fourth ventricle to the closed medulla and central canal.'}}"
new = "function brainstemDetail(level){const L=String(level||'');if(/midbrain/i.test(L)){const rostral=/Rostral/i.test(L);return{s:'Brainstem · '+(rostral?'rostral midbrain':'midbrain'),p:'Axial foremost',r:rostral?'At rostral midbrain level, the cerebral peduncles remain ventral, the substantia nigra territory lies just dorsal to them, the red nucleus territory is central, the aqueduct is midline, and the superior collicular tectum is dorsal.':'At caudal midbrain level, the cerebral peduncles are ventral, the tegmentum surrounds the aqueduct, and the dorsal tectum is dominated by inferior collicular territory. The superior cerebellar peduncles approach and decussate in this region.',n:rostral?['Ventral: cerebral peduncles','Between peduncle and tegmentum: substantia nigra territory','Central tegmentum: red nucleus territory','Midline: cerebral aqueduct','Dorsal: superior collicular tectum']:['Ventral: cerebral peduncles','Central: tegmentum and medial lemniscal territory','Midline: cerebral aqueduct','Dorsal: inferior collicular tectum','Central caudal midbrain: superior cerebellar peduncle decussation territory'],f:'Carries major ascending and descending pathways and contains nuclei important for ocular motor control, arousal and motor integration.',c:'Midbrain lesions can combine long-tract findings with oculomotor, pupillary, tremor or ataxic syndromes depending on the cross-sectional level.',t:'Scroll slowly between upper pons and diencephalon. Use the aqueduct as the midline anchor, then identify peduncular, tegmental and tectal compartments.'}}if(/pons/i.test(L)){const rostral=/Rostral/i.test(L);return{s:'Brainstem · '+(rostral?'rostral pons':'pons'),p:'Axial foremost',r:rostral?'The rostral pons is divided into ventral basis pontis and dorsal tegmentum. Large transverse pontocerebellar fibers and middle cerebellar peduncles become prominent laterally.':'The caudal pons retains a broad ventral basis and dorsal tegmentum. The fourth ventricle is posterior, with facial, abducens and vestibular nuclear territories concentrated dorsally at appropriate levels.',n:rostral?['Ventral: basis pontis with corticospinal and corticopontine fibers','Transverse pontine fibers cross the ventral pons','Lateral: middle cerebellar peduncles','Dorsal: pontine tegmentum','Posterior: fourth ventricle']:['Ventral: basis pontis and corticospinal tract territory','Dorsal: pontine tegmentum','Posterior midline: fourth ventricle','Dorsal caudal pons: facial colliculus and abducens/facial nerve territory','Lateral: vestibular and middle cerebellar peduncle regions'],f:'Relays corticocerebellar information and contains long tracts and cranial nerve systems involved in gaze, facial movement, sensation, hearing, balance and coordination.',c:'Pontine localization depends strongly on the axial level, so the dorsal tegmentum, ventral basis and cerebellar peduncles should be learned together.',t:'Scroll rostrocaudally through the pons and watch how the fourth ventricle, middle cerebellar peduncles and ventral basis change in proportion.'}}const rostral=/Rostral|Medulla level/i.test(L);return{s:'Brainstem · '+(rostral?'rostral medulla':'caudal medulla'),p:'Axial foremost',r:rostral?'The rostral or open medulla lies below the pons. The pyramids are ventromedial, the inferior olivary territory is anterolateral, the inferior cerebellar peduncles are posterolateral, and the fourth ventricle remains open dorsally.':'The caudal or closed medulla is more compact. The pyramids remain ventral, dorsal column nuclei occupy the posterior region at appropriate levels, and the fourth ventricle has narrowed toward the central canal.',n:rostral?['Ventromedial: pyramids','Anterolateral: inferior olivary territory','Posterolateral: inferior cerebellar peduncle territory','Dorsal: fourth ventricle','Tegmental region: medial lemniscus and lower cranial nerve territories']:['Ventral: pyramids','Posterior: gracile and cuneate nuclear territory','Central: central canal','Deep central region: sensory decussation and medial lemniscal formation depending on level','Lateral: spinothalamic and descending autonomic pathway territories'],f:'Contains vital autonomic centers, lower cranial nerve nuclei and ascending and descending long tracts.',c:'Medullary lesions can combine pyramidal, dorsal-column/medial lemniscal, spinothalamic, cerebellar and lower cranial nerve findings. Open and closed medulla should be distinguished on cross section.',t:'Scroll downward from the pontomedullary junction. Watch the fourth ventricle narrow and close while the pyramids, olives, dorsal column regions and central canal change together.'}}"
if old not in s:
    raise SystemExit('brainstemDetail block not found')
s = s.replace(old, new)

old_moved = "function moved(d){const v=d?.values||[],pos=d?.string?`Crosshair: ${d.string}`:'Crosshair moved';let j=0,h=0,a=0;if(jhuReady&&Number.isFinite(v[jhuIndex]?.value))j=Math.round(v[jhuIndex].value);if(hoReady&&Number.isFinite(v[hoIndex]?.value))h=Math.round(v[hoIndex].value);if(Number.isFinite(v[1]?.value))a=Math.round(v[1].value);if(j>0&&JHU_LABELS[j]){const nm=pretty(JHU_LABELS[j]);selectStructure('JHU',[j],nm);teacher(JHU_LABELS[j],j,'JHU');loc.textContent=pos+' · White matter: '+nm;return}if(h>0&&HO_LABELS[h]&&/ventricle/i.test(HO_LABELS[h])){selectStructure('HO',[h],HO_LABELS[h]);teacher(HO_LABELS[h],h,'HO');loc.textContent=pos+' · '+HO_LABELS[h];return}if(h===8){const level=brainstemLevel();selectStructure('HO',[8],level);teacherSpecial(level);loc.textContent=pos+' · Brainstem: '+level;return}if(a>0&&labels[a]){active(a);loc.textContent=pos+' · Region: '+pretty(labels[a]);return}if(h>0&&HO_LABELS[h]){selectStructure('HO',[h],HO_LABELS[h]);teacher(HO_LABELS[h],h,'HO');loc.textContent=pos+' · '+HO_LABELS[h];return}const nearA=nearestLabel('AAL',2);if(nearA>0&&labels[nearA]){active(nearA);loc.textContent=pos+' · Nearest atlas region: '+pretty(labels[nearA]);return}const nearH=hoReady?nearestLabel('HO',1):0;if(nearH>0&&HO_LABELS[nearH]){selectStructure('HO',[nearH],HO_LABELS[nearH]);teacher(HO_LABELS[nearH],nearH,'HO');loc.textContent=pos+' · Nearest structural label: '+HO_LABELS[nearH];return}setSel('MRI anatomy · no validated atlas boundary at this exact voxel');loc.textContent=pos+' · No validated named atlas label at this exact voxel'}"
new_moved = "function moved(d){const v=d?.values||[],pos=d?.string?`Crosshair: ${d.string}`:'Crosshair moved';let j=0,h=0,a=0;if(jhuReady&&Number.isFinite(v[jhuIndex]?.value))j=Math.round(v[jhuIndex].value);if(hoReady&&Number.isFinite(v[hoIndex]?.value))h=Math.round(v[hoIndex].value);if(Number.isFinite(v[1]?.value))a=Math.round(v[1].value);if(j>0&&JHU_LABELS[j]){const nm=pretty(JHU_LABELS[j]);selectStructure('JHU',[j],nm);teacher(JHU_LABELS[j],j,'JHU');loc.textContent=pos+' · White matter: '+nm;return}if(h>0&&HO_LABELS[h]&&/ventricle/i.test(HO_LABELS[h])){selectStructure('HO',[h],HO_LABELS[h]);teacher(HO_LABELS[h],h,'HO');loc.textContent=pos+' · '+HO_LABELS[h];return}if(h===8){const level=brainstemLevel();selectStructure('HO',[8],level);teacherSpecial(level);loc.textContent=pos+' · Brainstem cross section: '+level;return}if(a>0&&labels[a]){active(a);loc.textContent=pos+' · Region: '+pretty(labels[a]);return}if(h>0&&HO_LABELS[h]){selectStructure('HO',[h],HO_LABELS[h]);teacher(HO_LABELS[h],h,'HO');loc.textContent=pos+' · '+HO_LABELS[h];return}const vent=midlineVentricleAtCursor();if(vent){teacherSpecial(vent);loc.textContent=pos+' · Ventricular landmark: '+vent;return}const nearA=nearestLabel('AAL',4);if(nearA&&labels[nearA.id]){active(nearA.id);loc.textContent=pos+' · Nearest atlas region: '+pretty(labels[nearA.id]);return}const nearH=hoReady?nearestLabel('HO',2):null;if(nearH&&HO_LABELS[nearH.id]){selectStructure('HO',[nearH.id],HO_LABELS[nearH.id]);teacher(HO_LABELS[nearH.id],nearH.id,'HO');loc.textContent=pos+' · Nearest structural label: '+HO_LABELS[nearH.id];return}const nearJ=jhuReady?nearestLabel('JHU',2):null;if(nearJ&&JHU_LABELS[nearJ.id]){const nm=pretty(JHU_LABELS[nearJ.id]);selectStructure('JHU',[nearJ.id],nm);teacher(JHU_LABELS[nearJ.id],nearJ.id,'JHU');loc.textContent=pos+' · Nearest white-matter label: '+nm;return}setSel('MRI anatomy · no validated atlas boundary at this exact voxel');loc.textContent=pos+' · No validated named atlas label at this exact voxel'}"
if old_moved not in s:
    raise SystemExit('moved block not found')
s = s.replace(old_moved, new_moved)

